RECIPES_V3 = []
def R(**kw): RECIPES_V3.append(kw)
OVEN = lambda t, m, label=None, after='', mid=None: dict(kind='bake', temp=t, minutes=m, label=label or str(m), sub='minutos', after=after, **({'mid': mid} if mid else {}))
TOP = lambda title, batches, done: dict(kind='top', title=title, batches=batches, done=done)
FILL = lambda title, batches, target='dish', mix=None, mixText=None: dict(kind='fill', target=target, title=title, batches=batches, **({'mix': mix, 'mixText': mixText} if mix else {}))
CHILL = lambda label, sub='minutos', title=['Frigorífico']: dict(kind='chill', title=title, label=label, sub=sub)

